// Android library (AAR) of the Kotlin bindings of kraken-ffi, with the libraries of every ABI:
//
//   scripts/build.sh android && scripts/bindings.sh kotlin
//   ./gradlew :kraken-android:assembleRelease             build/outputs/aar/kraken-android-release.aar
//   ./gradlew :kraken-android:connectedDebugAndroidTest   the tests of platforms/kotlin, on a device / emulator
//
// AGP 9 compiles the Kotlin sources itself: no org.jetbrains.kotlin.android plugin
plugins {
    alias(additionals.plugins.android.library)
    id("jvmCompat")
}

// generated by scripts/bindings.sh kotlin
val bindings = rootDir.resolve("dist/bindings/kotlin")
// built by scripts/build.sh android: Rust target -> Android ABI
val abis = mapOf(
    "aarch64-linux-android" to "arm64-v8a",
    "armv7-linux-androideabi" to "armeabi-v7a",
    "i686-linux-android" to "x86",
    "x86_64-linux-android" to "x86_64",
)
val jniLibsDir = layout.buildDirectory.dir("jniLibs").get().asFile

android {
    namespace = "com.crypt0p1a.kraken"
    compileSdk = additionals.versions.compileSdkVersion.get().toInt()

    defaultConfig {
        minSdk = additionals.versions.minSdkVersion.get().toInt()
        testInstrumentationRunner = "androidx.test.runner.AndroidJUnitRunner"
        consumerProguardFiles("consumer-rules.pro")
    }

    sourceSets {
        getByName("main") {
            kotlin.directories += bindings.path
            jniLibs.directories += jniLibsDir.path
        }
        // the tests of the JVM, run on the device
        getByName("androidTest") {
            kotlin.directories += rootDir.resolve("platforms/kotlin/src/test/kotlin").path
        }
    }

    compileOptions {
        val version = JavaVersion.toVersion(rootProject.extra["javaVersion"] as String)
        sourceCompatibility = version
        targetCompatibility = version
    }

    packaging {
        resources.excludes += setOf("META-INF/LICENSE*", "META-INF/AL2.0", "META-INF/LGPL2.1")
    }
}

// the uniffi bindings hold unused expressions, flagged since Kotlin 2.4
kotlin {
    compilerOptions {
        freeCompilerArgs.add("-Xwarning-level=UNUSED_EXPRESSION:disabled")
    }
}

dependencies {
    implementation(libs.jna) { artifact { type = "aar" } }
    implementation(additionals.kotlinx.coroutines.core)

    androidTestImplementation(additionals.androidx.test.runner)
    androidTestImplementation(additionals.junit)
    androidTestImplementation(additionals.kotlinx.coroutines.test)
    androidTestImplementation(additionals.okhttp.mockwebserver)
}

/** the bindings and at least one libkraken_ffi.so: a check of its own, copyJniLibs is skipped without them */
val checkKrakenLibraries = tasks.register("checkKrakenLibraries") {
    doLast {
        check(bindings.resolve("uniffi").isDirectory) {
            "no bindings in $bindings: run scripts/bindings.sh kotlin"
        }
        val missing = abis.keys.filterNot { rootDir.resolve("dist/$it/libkraken_ffi.so").isFile }
        check(missing.size < abis.size) { "no Android library in dist/: run scripts/build.sh android" }
        if (missing.isNotEmpty()) logger.warn("kraken-android: no library for $missing")
    }
}

/** libkraken_ffi.so of each ABI, from dist/<target> */
val copyJniLibs = tasks.register<Sync>("copyJniLibs") {
    dependsOn(checkKrakenLibraries)
    abis.forEach { (target, abi) ->
        from(rootDir.resolve("dist/$target")) {
            include("libkraken_ffi.so")
            into(abi)
        }
    }
    into(jniLibsDir)
}

tasks.named("preBuild") {
    dependsOn(copyJniLibs)
}
